function kutu(genislik, padding, border, margin, sizing) {
  let icerik, gorunen;
  if (sizing === 'border-box') {
    gorunen = genislik;
    icerik = genislik - 2 * padding - 2 * border;
  } else {
    icerik = genislik;
    gorunen = genislik + 2 * padding + 2 * border;
  }
  return { icerik: icerik, gorunen: gorunen, yer: gorunen + 2 * margin };
}

