function flexDagit(kapsayici, ogeler) {
  const basisToplam = ogeler.reduce((t, o) => t + o.basis, 0);
  const artan = kapsayici - basisToplam;
  const payToplam = ogeler.reduce((t, o) => t + o.grow, 0);
  return ogeler.map(o => o.basis + artan * (o.grow / payToplam));
}

