function gridHesap(kapsayici, izler, gap) {
  const gapToplam = gap * (izler.length - 1);
  const sabit = izler.filter(i => i.tip === 'px').reduce((t, i) => t + i.deger, 0);
  const frToplam = izler.filter(i => i.tip === 'fr').reduce((t, i) => t + i.deger, 0);
  const kalan = kapsayici - gapToplam - sabit;
  return izler.map(i => i.tip === 'px' ? i.deger : kalan * (i.deger / frToplam));
}

const a = gridHesap(1000, [
