function classListYap(baslangic) {
  const kume = new Set(baslangic.split(' ').filter(Boolean));
  return {
    add: (s) => { kume.add(s); },
    remove: (s) => { kume.delete(s); },
    toggle: (s) => { if (kume.has(s)) { kume.delete(s); return false; } kume.add(s); return true; },
    contains: (s) => kume.has(s),
    deger: () => [...kume].join(' ')
  };
}

