import crypto from 'node:crypto';

function etagUret(govde) {
  return '"' + crypto.createHash('sha1').update(govde).digest('base64url').slice(0, 16) + '"';
}

function istek(govde, gelenEtag) {
  const etag = etagUret(govde);
  if (gelenEtag === etag) return { kod: 304, etag: etag, bayt: 0 };
  return { kod: 200, etag: etag, bayt: Buffer.byteLength(govde) };
}

const v1 = 'body { color: #111; }';
