function ayristir(cc) {
  const o = {};
  for (const p of cc.split(',')) {
    const [ad, deger] = p.trim().split('=');
    o[ad] = deger === undefined ? true : Number(deger);
  }
  return o;
}

function tazeMi(cc, yas) {
  const k = ayristir(cc);
  if (k['no-store']) return 'hic saklanmaz';
  if (k['no-cache']) return 'saklanir ama her kullanimda dogrulanir';
  if (k['max-age'] !== undefined) {
    return yas < k['max-age'] ? 'taze, agdan sorulmaz' : 'bayat, dogrulama gerekli';
  }
  return 'belirsiz';
}

for (const [cc, yas] of [['public, max-age=31536000, immutable', 100],
