import crypto from 'node:crypto';

function karma(icerik) {
  return crypto.createHash('sha256').update(icerik).digest('hex').slice(0, 8);
}

function varlikAdi(ad, icerik) {
  const i = ad.lastIndexOf('.');
  return ad.slice(0, i) + '.' + karma(icerik) + ad.slice(i);
}

function politika(ad) {
  if (ad.endsWith('.html')) return 'no-cache';
  if (/\.[0-9a-f]{8}\.(js|css|woff2)$/.test(ad)) return 'public, max-age=31536000, immutable';
  return 'public, max-age=3600';
}

const stil1 = 'body{margin:0}';
const stil2 = 'body{margin:0;padding:0}';

const a1 = varlikAdi('stil.css', stil1);
const a2 = varlikAdi('stil.css', stil2);
console.log('surum 1: ' + a1);
console.log('surum 2: ' + a2);
console.log('ad degisti: ' + (a1 !== a2));

for (const ad of [a1, 'index.html', 'logo.svg']) {
  console.log(ad + ' -> ' + politika(ad));
}

// Ayni icerik her zaman ayni adi uretir (tekrarlanabilir derleme)
console.log('tekrarlanabilir: ' + (varlikAdi('stil.css', stil1) === a1));
